/**
 * Selectable national grid emission-factor policy for Indian MSME inventories.
 * Default national policy is CEA Weighted Average 0.710 (FY 2024-25).
 * Optional MSME conservative proxy 0.80 remains selectable.
 */

const CARBON_SHARED = require('./carbonEmissionDefaults.json');
const { DEFAULT_FACTOR_REGISTRY } = require('./emissionFactorRegistry');

const POLICY_MSME_PROXY = 'msme_proxy_0_80';
const POLICY_CEA_WA = 'cea_wa_0_710';

const resolvePolicyConfig = () => CARBON_SHARED.nationalGridFactorPolicy || {};

const listNationalGridFactorPolicies = () => {
  const options = resolvePolicyConfig().options || {};
  return Object.entries(options).map(([id, row]) => ({
    id,
    factor: Number(row.factor),
    label: row.label || id,
    description: row.description || '',
    source: row.source || null
  }));
};

const normalizeNationalGridFactorPolicy = (raw) => {
  const text = String(raw || '').trim();
  const options = resolvePolicyConfig().options || {};
  if (text && options[text]) return text;
  const fallback = resolvePolicyConfig().default || POLICY_CEA_WA;
  return options[fallback] ? fallback : POLICY_CEA_WA;
};

/**
 * Resolve the national grid factor kgCO2e/kWh. State tokens are not applied.
 */
const resolveNationalGridFactorKgPerKwh = (policyRaw = null, options = {}) => {
  const policy = normalizeNationalGridFactorPolicy(
    policyRaw
    || options.boundary?.nationalGridFactorPolicy
    || options.nationalGridFactorPolicy
    || options.msmeData?.operations?.ghgOperationalBoundary?.nationalGridFactorPolicy
  );
  const option = resolvePolicyConfig().options?.[policy];
  if (option && Number.isFinite(Number(option.factor)) && Number(option.factor) > 0) {
    return {
      policy,
      factor: Number(option.factor),
      label: option.label || policy,
      source: option.source || null
    };
  }
  const registryFactor = Number(DEFAULT_FACTOR_REGISTRY?.electricity_grid_india?.factor) || 0.71;
  return {
    policy: POLICY_MSME_PROXY,
    factor: registryFactor,
    label: 'MSME national proxy (registry)',
    source: DEFAULT_FACTOR_REGISTRY?.electricity_grid_india?.sourceDocument || null
  };
};

module.exports = {
  POLICY_MSME_PROXY,
  POLICY_CEA_WA,
  listNationalGridFactorPolicies,
  normalizeNationalGridFactorPolicy,
  resolveNationalGridFactorKgPerKwh
};
