/**
 * Shared carbon inventory analytics helpers (backend + tooling).
 * GHG Protocol–aligned scope 3 categories, data-quality tiers, and factor lineage.
 */

const CARBON_SHARED = require('./carbonEmissionDefaults.json');
const {
  DEFAULT_FACTOR_REGISTRY: SHARED_FACTOR_REGISTRY
} = require('./emissionFactorRegistry');

const QUANTIFICATION_METHODS = Object.freeze({
  ACTIVITY: 'activity_based',
  SPEND_PROXY: 'spend_proxy',
  SUPPLIER_PRIMARY: 'supplier_primary',
  ESTIMATE: 'estimate',
  EXCLUDED: 'excluded_non_emitting_financial_flow'
});

const DATA_QUALITY_TIERS = Object.freeze({
  TIER_1: 'tier_1_activity',
  TIER_2: 'tier_2_spend_proxy',
  TIER_3: 'tier_3_estimate',
  EXCLUDED: 'excluded'
});

/** GHG Protocol Scope 3 category keys (Corporate Standard). */
const GHG_SCOPE3_CATEGORY_KEYS = Object.freeze([
  'cat1_purchased_goods',
  'cat2_capital_goods',
  'cat3_fuel_energy_related',
  'cat4_upstream_transport',
  'cat5_waste',
  'cat6_business_travel',
  'cat7_employee_commuting',
  'cat8_upstream_leased_assets',
  'cat9_downstream_transport',
  'cat10_processing_sold_products',
  'cat11_use_sold_products',
  'cat12_end_of_life',
  'cat13_downstream_leased_assets',
  'cat14_franchises',
  'cat15_investments',
  'unclassified_indirect'
]);

const GHG_SCOPE3_LABELS = Object.freeze({
  cat1_purchased_goods: 'Cat. 1 — Purchased goods & services',
  cat2_capital_goods: 'Cat. 2 — Capital goods',
  cat3_fuel_energy_related: 'Cat. 3 — Fuel- and energy-related activities',
  cat4_upstream_transport: 'Cat. 4 — Upstream transportation & distribution',
  cat5_waste: 'Cat. 5 — Waste generated in operations',
  cat6_business_travel: 'Cat. 6 — Business travel',
  cat7_employee_commuting: 'Cat. 7 — Employee commuting',
  cat8_upstream_leased_assets: 'Cat. 8 — Upstream leased assets',
  cat9_downstream_transport: 'Cat. 9 — Downstream transportation & distribution',
  cat10_processing_sold_products: 'Cat. 10 — Processing of sold products',
  cat11_use_sold_products: 'Cat. 11 — Use of sold products',
  cat12_end_of_life: 'Cat. 12 — End-of-life treatment of sold products',
  cat13_downstream_leased_assets: 'Cat. 13 — Downstream leased assets',
  cat14_franchises: 'Cat. 14 — Franchises',
  cat15_investments: 'Cat. 15 — Investments',
  unclassified_indirect: 'Unclassified indirect (review allocation)'
});

const DEFAULT_FACTOR_REGISTRY = SHARED_FACTOR_REGISTRY;

const ORGANIZATIONAL_BOUNDARY_DEFAULT = Object.freeze({
  approach: 'operational_control',
  consolidation: 'operational_control',
  description: 'Emissions from operations under the reporting entity’s operational control.'
});

/** Activity units recognized for tier-1 quantification (aligned with OCR consumption_intelligence_v2). */
const ACTIVITY_BASE_UNITS = Object.freeze([
  'kwh',
  'liter',
  'kg',
  'm3',
  'km',
  'passenger_km',
  'kiloliter',
  'scm',
  'tonne',
  'tonkm',
  'gb',
  'gj',
  'service_unit',
  'night',
  'hour'
]);

const toFinite = (value, fallback = 0) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
};

const normalizeUnit = (unit) => {
  const normalized = String(unit || '').toLowerCase().trim();
  if (!normalized) return null;
  if (['kwh', 'kw-h', 'kw·h', 'kilowatt-hour', 'kilowatt hour', 'kilowatthour'].includes(normalized)) {
    return 'kwh';
  }
  if (['kl', 'kiloliter', 'kilolitre', 'kiloliters', 'kilolitres', 'kld'].includes(normalized)) {
    return 'kiloliter';
  }
  if (['l', 'lt', 'ltr', 'litre', 'litres', 'liter', 'liters'].includes(normalized)) {
    return 'liter';
  }
  if (['kg', 'kgs', 'kilogram', 'kilograms'].includes(normalized)) {
    return 'kg';
  }
  if (['m3', 'm^3', 'cubic meter', 'cubic metre', 'cubic meters', 'cubic metres'].includes(normalized)) {
    return 'm3';
  }
  if (['km', 'kilometer', 'kilometers', 'kilometre', 'kilometres'].includes(normalized)) {
    return 'km';
  }
  if (['pkm', 'passenger-km', 'passenger km', 'passenger_km'].includes(normalized)) {
    return 'passenger_km';
  }
  if (['scm', 'smc', 'standard cubic meter', 'standard cubic metre'].includes(normalized)) {
    return 'scm';
  }
  if (['t', 'mt', 'ton', 'tonne', 'tonnes', 'metric ton', 'metric tonne'].includes(normalized)) {
    return 'tonne';
  }
  if (['ton-km', 'tonne-km', 'tonkm', 'tonnekm', 't-km'].includes(normalized)) {
    return 'tonkm';
  }
  if (['gb', 'gigabyte', 'gigabytes'].includes(normalized)) {
    return 'gb';
  }
  if (['gj', 'gigajoule', 'gigajoules'].includes(normalized)) {
    return 'gj';
  }
  if ([
    'unit', 'units', 'meal', 'meals', 'service_unit',
    'service unit', 'service-unit', 'service units',
    'job', 'jobs', 'job card', 'job-card', 'job_card',
    'visit', 'visits'
  ].includes(normalized)) {
    return 'service_unit';
  }
  if (['night', 'nights', 'room_night', 'room-night'].includes(normalized)) return 'night';
  if (['hour', 'hours', 'hr', 'hrs'].includes(normalized)) return 'hour';
  return normalized;
};

const extractActivityQuantity = (transaction = {}) => {
  const unit = normalizeUnit(transaction.unit || transaction.metadata?.unit);
  const quantity = toFinite(
    transaction.quantity ??
    transaction.metadata?.quantity ??
    transaction.metadata?.kwh ??
    transaction.metadata?.liters ??
    transaction.kwh ??
    transaction.liters,
    0
  );
  if (quantity <= 0) {
    return { quantity: 0, unit: null, activityType: null };
  }
  if (unit === 'kwh') {
    return { quantity, unit: 'kwh', activityType: 'electricity' };
  }
  if (unit === 'liter') {
    return { quantity, unit: 'liter', activityType: 'fuel_or_water' };
  }
  if (unit === 'kiloliter') {
    return { quantity: quantity * 1000, unit: 'liter', activityType: 'water' };
  }
  if (unit === 'kg') {
    return { quantity, unit: 'kg', activityType: 'material' };
  }
  if (unit === 'm3') {
    return { quantity, unit: 'm3', activityType: 'natural_gas' };
  }
  if (unit === 'km' || unit === 'passenger_km') {
    return { quantity, unit, activityType: 'distance' };
  }
  if (unit === 'scm') {
    return { quantity, unit, activityType: 'natural_gas' };
  }
  if (unit === 'tonne') {
    return { quantity, unit, activityType: 'material_mass' };
  }
  if (unit === 'tonkm') {
    return { quantity, unit, activityType: 'freight_distance' };
  }
  if (unit === 'gb') {
    return { quantity, unit, activityType: 'data_transfer' };
  }
  if (unit === 'gj') {
    return { quantity, unit, activityType: 'energy_thermal' };
  }
  if (unit === 'service_unit') {
    return { quantity, unit, activityType: 'service_count' };
  }
  return { quantity, unit: unit || 'unit', activityType: 'generic' };
};

const hasSupplierPrimaryEmissions = (transaction = {}) => {
  const metadata = transaction.metadata || {};
  const total = Number(metadata.supplierTotalKgCo2e);
  if (Number.isFinite(total) && total > 0) {
    return true;
  }
  const factorValue = Number(metadata.supplierPrimaryFactor?.value);
  return Number.isFinite(factorValue) && factorValue > 0;
};

const resolveSupplierPrimaryKg = (transaction = {}) => {
  const metadata = transaction.metadata || {};
  const total = Number(metadata.supplierTotalKgCo2e);
  if (Number.isFinite(total) && total > 0) {
    return total;
  }

  const factor = metadata.supplierPrimaryFactor || {};
  const factorValue = Number(factor.value);
  if (!Number.isFinite(factorValue) || factorValue <= 0) {
    return null;
  }

  if (String(factor.unit || '').includes('kgCO2e_per_INR')) {
    const amount = toFinite(transaction.amount, 0);
    return amount > 0 ? amount * factorValue : null;
  }

  const unit = normalizeUnit(transaction.unit || metadata.unit);
  const quantity = toFinite(
    transaction.quantity ??
    metadata.quantity ??
    metadata.kg,
    0
  );
  if (quantity > 0 && (unit === 'kg' || String(factor.unit || '').includes('kg'))) {
    return quantity * factorValue;
  }

  return null;
};

/**
 * Accounting export rows park the sheet quantity on metadata.importedActivity.
 * The calculation uses that quantity for named activities. Analytics and
 * reports use the same rule, including when a saved footprint is still spend.
 */
const accountingExportParkedActivityCalculated = (transaction = {}) => {
  const imported = transaction.metadata?.importedActivity || {};
  const quantity = toFinite(imported.quantity, 0);
  const unit = normalizeUnit(imported.unit);
  if (!(quantity > 0) || !unit || unit === 'service_unit') return false;
  const category = String(transaction.category || '').toLowerCase();
  const subcategory = String(transaction.subcategory || '').toLowerCase();
  const text = `${transaction.description || ''} ${transaction.memo || ''} ${transaction.narration || ''} ${subcategory}`.toLowerCase();
  if (unit === 'hour') {
    return /\b(work from home|wfh|remote work|homeworking)\b/.test(text);
  }
  if (unit === 'kwh') {
    if (category === 'energy' || category === 'utilities') return true;
    return /\b(homeworking|work from home|wfh|remote work|leas(?:e|ed|es|ing)|franchise|job work|processing|customer use phase|use of sold|use phase)\b/.test(text);
  }
  if (unit === 'kg' || unit === 'tonne') {
    if (category === 'waste_management') return true;
    if (subcategory === 'investment' || subcategory === 'investments') return true;
    return /\b(end-?of-?life|disposal of sold|product disposal|equity stake|financed emission|investment)\b/.test(text);
  }
  if (unit === 'liter' || unit === 'kiloliter') {
    if (category === 'water') return false;
    return /\b(diesel|petrol|gasoline|lpg|cng|coal|furnace oil|fuel oil|natural gas|hsd)\b/.test(text)
      || ['diesel', 'petrol', 'lpg', 'cng', 'coal', 'natural_gas', 'furnace_oil', 'fuel_oil', 'fuel'].includes(subcategory);
  }
  return false;
};

const resolveQuantificationMethod = (transaction = {}, category = '') => {
  if (transaction.excludeFromCarbonFootprint === true) {
    return QUANTIFICATION_METHODS.EXCLUDED;
  }
  if (hasSupplierPrimaryEmissions(transaction)) {
    return QUANTIFICATION_METHODS.SUPPLIER_PRIMARY;
  }
  if (accountingExportParkedActivityCalculated(transaction)) {
    return QUANTIFICATION_METHODS.ACTIVITY;
  }
  const quantificationOrigin = String(transaction.metadata?.quantificationOrigin || '');
  const carbonInputBasis = String(transaction.metadata?.carbonInputBasis || '').toLowerCase();
  if (quantificationOrigin === 'accounting_export' && carbonInputBasis !== 'activity') {
    return toFinite(transaction.amount, 0) > 0
      ? QUANTIFICATION_METHODS.SPEND_PROXY
      : QUANTIFICATION_METHODS.ESTIMATE;
  }
  const activity = extractActivityQuantity(transaction);
  if (activity.quantity > 0 && ACTIVITY_BASE_UNITS.includes(activity.unit)) {
    return QUANTIFICATION_METHODS.ACTIVITY;
  }
  const desc = `${transaction.description || ''} ${transaction.memo || ''}`.toLowerCase();
  if (/\b(estimate|approx|assumed)\b/.test(desc)) {
    return QUANTIFICATION_METHODS.ESTIMATE;
  }
  if (toFinite(transaction.amount, 0) > 0) {
    return QUANTIFICATION_METHODS.SPEND_PROXY;
  }
  return QUANTIFICATION_METHODS.ESTIMATE;
};

const isPlainObject = (value) => (
  value != null && typeof value === 'object' && !Array.isArray(value)
);

// Assurance follows an explicit approval record. A source name, an
// auditorReference match, or a sentence that merely mentions an authority
// does not approve the factor.
const explicitFactorApproval = (row = {}) => (
  isPlainObject(row.approval) ? row.approval : null
);

const isAssuranceGradeLineage = (lineage = {}) => {
  const approval = explicitFactorApproval(lineage);
  return Boolean(approval) && approval.status === 'approved';
};

const resolveDataQualityTier = (quantificationMethod) => {
  switch (quantificationMethod) {
    case QUANTIFICATION_METHODS.ACTIVITY:
    case QUANTIFICATION_METHODS.SUPPLIER_PRIMARY:
      return DATA_QUALITY_TIERS.TIER_1;
    case QUANTIFICATION_METHODS.SPEND_PROXY:
      return DATA_QUALITY_TIERS.TIER_2;
    case QUANTIFICATION_METHODS.EXCLUDED:
      return DATA_QUALITY_TIERS.EXCLUDED;
    default:
      return DATA_QUALITY_TIERS.TIER_3;
  }
};

const isSoldProductProcessing = (desc = '') => (
  desc.includes('contract manufactur')
  || desc.includes('job work')
  || /\bprocessing of sold\b/.test(desc)
  || /\bdownstream processing\b/.test(desc)
  || (/\bprocessing\b/.test(desc) && /\bsold products?\b/.test(desc))
);

const { consultantLinkedScope3Key } = require('./consultantScope3Boundary');

const resolveScope3GhgCategory = (transaction = {}) => {
  const linkedCategory = consultantLinkedScope3Key(transaction);
  if (linkedCategory) return linkedCategory;
  const category = String(transaction.category || '').toLowerCase();
  const subcategory = String(transaction.subcategory || '').toLowerCase();
  const desc = `${transaction.description || ''} ${transaction.memo || ''} ${transaction.narration || ''}`
    .toLowerCase();
  const activityUnit = String(transaction.unit || transaction.unitRaw || '')
    .toLowerCase()
    .replace(/[\s_-]+/g, '');
  // Tonne and tonne-km are freight. "Rail" in that text is a freight mode, not a passenger ticket.
  const freightActivity = activityUnit === 'tonkm'
    || activityUnit === 'tonnekm'
    || activityUnit === 'tkm'
    || activityUnit === 'tonne'
    || activityUnit === 'ton';

  if (category === 'raw_materials' || subcategory.includes('capital')) {
    return subcategory.includes('capital') ? 'cat2_capital_goods' : 'cat1_purchased_goods';
  }
  if (category === 'waste_management') {
    return 'cat5_waste';
  }
  const utilityType = String(transaction.metadata?.utilityType || '').toLowerCase();
  const sewageBill = category === 'sewage'
    || category === 'sewage_charges'
    || subcategory === 'sewage'
    || subcategory === 'sewage_charges'
    || (category === 'water' && utilityType === 'sewage');
  if (sewageBill) return 'sewage';
  if (category === 'water' || category === 'water_supply' || category === 'purchased_water') {
    return 'water';
  }
  if (freightActivity) {
    const downstreamFreight = /\b(outbound|customer delivery|dispatch)\b/.test(desc);
    return downstreamFreight ? 'cat9_downstream_transport' : 'cat4_upstream_transport';
  }
  if (desc.includes('commut') || subcategory === 'commuting' || subcategory === 'employee_commuting') {
    return 'cat7_employee_commuting';
  }
  if (desc.includes('work from home') || desc.includes('wfh') || desc.includes('remote work') || desc.includes('homeworking')) {
    return 'cat7_employee_commuting';
  }
  if (!freightActivity && (desc.includes('travel') || desc.includes('flight') || desc.includes('hotel') || desc.includes('airline')
    || desc.includes('cab') || desc.includes('taxi') || desc.includes('rail') || desc.includes('train ticket'))) {
    return 'cat6_business_travel';
  }
  if (/\bleas(?:e|ed|es|ing)\b/.test(desc) && (desc.includes('upstream') || desc.includes('rented'))) {
    return 'cat8_upstream_leased_assets';
  }
  if (/\bleas(?:e|ed|es|ing)\b/.test(desc) || desc.includes('rental asset')) {
    return 'cat13_downstream_leased_assets';
  }
  if (desc.includes('franchise')) {
    return 'cat14_franchises';
  }
  if (desc.includes('investment') || desc.includes('portfolio') || desc.includes('equity stake')
    || subcategory === 'investment' || subcategory === 'investments') {
    return 'cat15_investments';
  }
  if (isSoldProductProcessing(desc)) {
    return 'cat10_processing_sold_products';
  }
  if (desc.includes('use of sold') || desc.includes('product use') || desc.includes('customer use phase')) {
    return 'cat11_use_sold_products';
  }
  if (desc.includes('end of life') || desc.includes('end-of-life') || desc.includes('disposal of sold')
    || desc.includes('product disposal')) {
    return 'cat12_end_of_life';
  }
  if (category === 'travel' || subcategory === 'business_travel') {
    return 'cat6_business_travel';
  }
  if (category === 'transportation') {
    if (desc.includes('commut') || subcategory === 'commuting') {
      return 'cat7_employee_commuting';
    }
    if (!freightActivity && (desc.includes('flight') || desc.includes('airline') || desc.includes('air ticket') || /\bair\s*travel\b/.test(desc) || subcategory === 'flight' || subcategory === 'air_travel')) {
      return 'cat6_business_travel';
    }
    if (!freightActivity && (desc.includes('hotel') || desc.includes('travel') || subcategory === 'travel')) {
      return 'cat6_business_travel';
    }
    if (desc.includes('deliver') || desc.includes('dispatch') || desc.includes('outbound') || desc.includes('customer delivery')) {
      return 'cat9_downstream_transport';
    }
    if (desc.includes('freight') || desc.includes('logistics') || desc.includes('courier') || desc.includes('inbound')) {
      return 'cat4_upstream_transport';
    }
    return 'cat4_upstream_transport';
  }
  if (desc.includes('commut') || subcategory === 'commuting') {
    return 'cat7_employee_commuting';
  }
  if (!freightActivity && (desc.includes('travel') || desc.includes('flight') || desc.includes('hotel') || desc.includes('airline')
    || desc.includes('rail') || desc.includes('train ticket'))) {
    return 'cat6_business_travel';
  }
  if (/\bleas(?:e|ed|es|ing)\b/.test(desc) && (desc.includes('upstream') || desc.includes('rented'))) {
    return 'cat8_upstream_leased_assets';
  }
  if (/\bleas(?:e|ed|es|ing)\b/.test(desc)) {
    return 'cat13_downstream_leased_assets';
  }
  if (desc.includes('franchise')) {
    return 'cat14_franchises';
  }
  if (desc.includes('investment') || desc.includes('portfolio')
    || subcategory === 'investment' || subcategory === 'investments') {
    return 'cat15_investments';
  }
  if (isSoldProductProcessing(desc)) {
    return 'cat10_processing_sold_products';
  }
  if (desc.includes('use of sold') || desc.includes('product use')) {
    return 'cat11_use_sold_products';
  }
  if (desc.includes('end of life') || desc.includes('end-of-life') || desc.includes('disposal of sold')) {
    return 'cat12_end_of_life';
  }
  if (category === 'energy' && (desc.includes('td loss') || desc.includes('transmission'))) {
    return 'cat3_fuel_energy_related';
  }
  if (category === 'maintenance') {
    return 'maintenance';
  }
  if (/\b(process\s*emission|calcination|clinker)\b/.test(desc)) {
    return '';
  }
  if (category === 'other') {
    return 'other';
  }
  if (['utilities', 'services', 'equipment'].includes(category)) {
    return 'cat1_purchased_goods';
  }
  return 'unclassified_indirect';
};

const utilityActivityFactorId = (transaction = {}, subcategory = '') => {
  const sub = String(subcategory || transaction.subcategory || '').toLowerCase();
  const desc = `${transaction.description || ''} ${transaction.memo || ''} ${transaction.narration || ''}`.toLowerCase();
  if (
    sub === 'sewage'
    || sub === 'sewage_charges'
    || /sewage|sewerage/.test(sub)
    || /\b(sewage|sewerage)\b/.test(desc)
  ) {
    return 'sewage_disposal';
  }
  if (
    sub === 'treatment'
    || sub === 'wastewater'
    || /wastewater|waste_water|effluent/.test(sub)
    || /\b(wastewater|waste water|effluent treatment)\b/.test(desc)
  ) {
    return 'wastewater_treatment';
  }
  if (
    ['water', 'water_supply', 'water_bill', 'supply', 'consumption', 'purchased_water'].includes(sub)
    || /\b(water supply|water bill|water charges|piped water|water-board|water board|jal board|utility water)\b/.test(desc)
  ) {
    return 'water_consumption';
  }
  return null;
};

const resolveFactorLineage = (transaction = {}, category = '', subcategory = '') => {
  const normalizedCategory = String(category || transaction.category || '').toLowerCase();
  const normalizedSub = String(subcategory || transaction.subcategory || '').toLowerCase();
  const quantificationMethod = resolveQuantificationMethod(transaction, normalizedCategory);
  const withMethod = (row) => (row ? { ...row, quantificationMethod } : null);

  // Prefer agent-stamped fuel classification factor id when present.
  const classifiedFactorId = transaction.metadata?.fuelClassification?.factorId;
  if (classifiedFactorId && DEFAULT_FACTOR_REGISTRY[classifiedFactorId]) {
    return withMethod(DEFAULT_FACTOR_REGISTRY[classifiedFactorId]);
  }

  const fuelFactorBySub = {
    diesel: 'fuel_diesel',
    petrol: 'fuel_petrol',
    lpg: 'fuel_lpg',
    cng: 'fuel_cng',
    coal: 'fuel_coal',
    natural_gas: 'fuel_natural_gas'
  };

  if (normalizedCategory === 'energy' || normalizedCategory === 'utilities') {
    if (fuelFactorBySub[normalizedSub]) {
      return withMethod(DEFAULT_FACTOR_REGISTRY[fuelFactorBySub[normalizedSub]]);
    }
    if (['fossil_fuel', 'fuel', 'gas', 'heating', 'boiler', 'furnace_oil', 'fuel_oil'].includes(normalizedSub)) {
      // No species: do not stamp a diesel factor on a row the calculator refused.
      return null;
    }
    if (normalizedSub === 'renewable' || normalizedSub === 'solar') {
      return withMethod(DEFAULT_FACTOR_REGISTRY.electricity_renewable);
    }
    if (normalizedSub === 'mixed') {
      return withMethod(DEFAULT_FACTOR_REGISTRY.electricity_mixed);
    }
    if (normalizedCategory === 'utilities') {
      const utilityFactorId = utilityActivityFactorId(transaction, normalizedSub);
      if (utilityFactorId && DEFAULT_FACTOR_REGISTRY[utilityFactorId]) {
        return withMethod(DEFAULT_FACTOR_REGISTRY[utilityFactorId]);
      }
    }
    return withMethod(DEFAULT_FACTOR_REGISTRY.electricity_grid_india);
  }

  if (normalizedCategory === 'water') {
    if (normalizedSub === 'sewage' || normalizedSub === 'sewage_charges') {
      return withMethod(DEFAULT_FACTOR_REGISTRY.sewage_disposal);
    }
    if (normalizedSub === 'treatment' || normalizedSub === 'wastewater') {
      return withMethod(DEFAULT_FACTOR_REGISTRY.wastewater_treatment);
    }
    return withMethod(DEFAULT_FACTOR_REGISTRY.water_consumption);
  }

  if (normalizedCategory === 'waste_management') {
    if (normalizedSub === 'hazardous') {
      return withMethod(DEFAULT_FACTOR_REGISTRY.waste_hazardous);
    }
    return withMethod(DEFAULT_FACTOR_REGISTRY.waste_solid);
  }

  if (normalizedCategory === 'raw_materials') {
    const materialId = `material_${normalizedSub}`;
    if (DEFAULT_FACTOR_REGISTRY[materialId]) {
      return withMethod(DEFAULT_FACTOR_REGISTRY[materialId]);
    }
  }

  if (normalizedCategory === 'transportation' || normalizedCategory === 'travel') {
    if (fuelFactorBySub[normalizedSub]) {
      return withMethod(DEFAULT_FACTOR_REGISTRY[fuelFactorBySub[normalizedSub]]);
    }
    const desc = `${transaction.description || ''} ${transaction.memo || ''}`.toLowerCase();
    if (desc.includes('flight') || desc.includes('airline') || normalizedSub === 'flight') {
      return null;
    }
    if (/\b(hotel|lodging|accommodation)\b/.test(desc)) {
      return null;
    }
    if (desc.includes('rail') || desc.includes('train') || normalizedSub === 'rail') {
      return withMethod(DEFAULT_FACTOR_REGISTRY.travel_rail_km);
    }
    if (desc.includes('commut') || normalizedSub === 'commuting') {
      return withMethod(DEFAULT_FACTOR_REGISTRY.commute_km);
    }
    if (desc.includes('lpg')) {
      return withMethod(DEFAULT_FACTOR_REGISTRY.fuel_lpg);
    }
    if (desc.includes('cng')) {
      return withMethod(DEFAULT_FACTOR_REGISTRY.fuel_cng);
    }
    if (/\b(cab|taxi|car|uber|ola|auto\s*rickshaw|sedan)\b/.test(desc) || normalizedSub === 'car' || normalizedSub === 'taxi') {
      return null;
    }
    return withMethod(DEFAULT_FACTOR_REGISTRY.travel_road_km);
  }

  if (normalizedCategory === 'maintenance') {
    const activity = extractActivityQuantity(transaction);
    const text = `${transaction.description || ''} ${transaction.subcategory || ''} ${transaction.item || ''}`.toLowerCase();
    if (activity.quantity > 0 && activity.unit === 'kg') {
      if (/\br[\s-]?134a\b|hfc[\s-]?134a\b|134a\b/.test(text) && DEFAULT_FACTOR_REGISTRY.refrigerant_r134a) {
        return withMethod(DEFAULT_FACTOR_REGISTRY.refrigerant_r134a);
      }
      if (/\br[\s-]?22\b|hcfc[\s-]?22\b|freon[\s-]?22\b/.test(text) && DEFAULT_FACTOR_REGISTRY.refrigerant_r22) {
        return withMethod(DEFAULT_FACTOR_REGISTRY.refrigerant_r22);
      }
    }
    return withMethod(DEFAULT_FACTOR_REGISTRY.maintenance_service_unit);
  }

  // True generic spend / estimate fallback only when no domain factor applies.
  if (quantificationMethod === QUANTIFICATION_METHODS.SPEND_PROXY
    || quantificationMethod === QUANTIFICATION_METHODS.ESTIMATE) {
    return withMethod(DEFAULT_FACTOR_REGISTRY.spend_generic);
  }

  return withMethod(DEFAULT_FACTOR_REGISTRY.spend_generic);
};

const DEFAULT_RENEWABLE_MARKET_FACTOR = 0.1;

const isProvisionalInventoryTransaction = (transaction = {}) => {
  const status = String(transaction.metadata?.inventoryStatus || '').toLowerCase();
  if (status === 'provisional') {
    return true;
  }
  return transaction.metadata?.pendingUserVerification === true;
};

const buildScope2DualReport = (transaction = {}, locationBasedKg = 0, options = {}) => {
  const co2 = Math.max(0, toFinite(locationBasedKg, 0));
  const subcategory = String(transaction.subcategory || '').toLowerCase();
  const desc = `${transaction.description || ''} ${transaction.memo || ''}`.toLowerCase();
  const isRenewable = subcategory === 'renewable'
    || transaction.sustainability?.isGreen === true
    || desc.includes('renewable')
    || desc.includes('green tariff')
    || desc.includes('solar ppa');

  const gridFactor = DEFAULT_FACTOR_REGISTRY.electricity_grid_india.factor;
  const renewableFactor = toFinite(
    options.renewableMarketFactor ?? transaction.renewableMarketFactor,
    DEFAULT_RENEWABLE_MARKET_FACTOR
  );
  const marketFactor = isRenewable ? renewableFactor : gridFactor;
  const ratio = gridFactor > 0 ? marketFactor / gridFactor : 1;

  return {
    locationBasedKg: co2,
    marketBasedKg: Math.round(co2 * ratio * 10000) / 10000,
    reportingBasis: isRenewable ? 'market_based_renewable_contract' : 'location_based_grid_average',
    dualReportRequired: true,
    renewableMarketFactor: isRenewable ? renewableFactor : null,
    note: isRenewable
      ? 'Market-based factor applied for contracted renewable / green tariff signals.'
      : 'National CEA grid factor used when a contractual supplier factor is unavailable.'
  };
};

/**
 * Activity / measurement relative uncertainty from quantification method + OCR accuracy.
 * Independent of emission-factor uncertainty; combined via RSS at inventory level.
 */
const resolveActivityRelativeUncertainty = (transaction = {}, footprint = {}) => {
  const explicit = toFinite(
    footprint.activityRelativeUncertainty
      ?? transaction.activityRelativeUncertainty
      ?? transaction.metadata?.activityRelativeUncertainty,
    null
  );
  if (explicit !== null && explicit >= 0) {
    return Math.min(0.9, explicit);
  }

  const method = footprint.quantificationMethod
    || resolveQuantificationMethod(transaction, transaction.category || 'other');
  let base;
  switch (method) {
    case QUANTIFICATION_METHODS.ACTIVITY:
      base = 0.05;
      break;
    case QUANTIFICATION_METHODS.SUPPLIER_PRIMARY:
      base = 0.08;
      break;
    case QUANTIFICATION_METHODS.SPEND_PROXY:
      base = 0.25;
      break;
    case QUANTIFICATION_METHODS.ESTIMATE:
      base = 0.4;
      break;
    case QUANTIFICATION_METHODS.EXCLUDED:
      return 0;
    default:
      base = 0.3;
  }

  const ocrAccuracy = toFinite(
    footprint.ocrAccuracy
      ?? transaction.metadata?.ocrAccuracy
      ?? transaction.ocrAccuracy
      ?? transaction.metadata?.extractedData?.ocrAccuracy,
    null
  );
  let ocrComponent = 0;
  if (ocrAccuracy !== null) {
    // Low OCR accuracy widens activity uncertainty (capped).
    ocrComponent = Math.max(0.02, Math.min(0.45, 1 - ocrAccuracy));
  }

  if (isProvisionalInventoryTransaction(transaction)) {
    base = Math.min(0.6, base + 0.1);
  }

  const combined = Math.sqrt((base ** 2) + (ocrComponent ** 2));
  return Math.round(Math.min(0.9, combined) * 10000) / 10000;
};

const combineFactorAndActivityRelativeUncertainty = (factorRu = 0.25, activityRu = 0) => {
  const factor = Math.max(0, toFinite(factorRu, 0.25));
  const activity = Math.max(0, toFinite(activityRu, 0));
  return Math.round(Math.sqrt((factor ** 2) + (activity ** 2)) * 10000) / 10000;
};

/**
 * Factor error is systematic. Vouchers that share a factor id are fully correlated.
 * Different factors combine by root-sum-square. Activity and OCR error on distinct
 * vouchers stays independent and combines by RSS.
 */
const factorCorrelationKey = (transaction = {}, footprint = {}, index = 0) => {
  const lineage = footprint.factorLineage || {};
  const factorId = lineage.id
    || lineage.factorId
    || transaction.metadata?.fuelClassification?.factorId
    || footprint.factorId
    || null;
  const key = String(factorId || '').trim();
  return key ? `factor:${key}` : `row:${index}`;
};

const computeCombinedInventoryUncertainty = (transactions = []) => {
  const rows = Array.isArray(transactions) ? transactions : [];
  let totalKg = 0;
  let contributingCount = 0;
  let activityOnlyRss = 0;
  const factorGroupAbsolute = new Map();

  rows.forEach((transaction, index) => {
    const footprint = transaction.carbonFootprint || {};
    const co2 = toFinite(footprint.co2Emissions, 0);
    if (co2 <= 0) {
      return;
    }
    const factorRelativeUncertainty = toFinite(
      footprint.factorLineage?.relativeUncertainty
        ?? footprint.factorLineage?.uncertainty?.relativeUncertainty,
      0.25
    );
    const activityRelativeUncertainty = toFinite(
      footprint.activityRelativeUncertainty,
      resolveActivityRelativeUncertainty(transaction, footprint)
    );
    totalKg += co2;
    const groupKey = factorCorrelationKey(transaction, footprint, index);
    factorGroupAbsolute.set(
      groupKey,
      (factorGroupAbsolute.get(groupKey) || 0) + (co2 * factorRelativeUncertainty)
    );
    activityOnlyRss += (co2 * activityRelativeUncertainty) ** 2;
    contributingCount += 1;
  });

  if (totalKg <= 0 || contributingCount === 0) {
    return {
      combinationMethod: 'root_sum_square',
      combinedRelativeUncertainty: null,
      combinedAbsoluteUncertaintyKg: null,
      lowerBoundKg: null,
      upperBoundKg: null,
      confidenceLevel: 0.95,
      contributingTransactionCount: 0,
      totalKg: 0,
      computed: false,
      components: {
        factorRelativeUncertainty: null,
        activityRelativeUncertainty: null
      }
    };
  }

  let factorOnlyRss = 0;
  factorGroupAbsolute.forEach((groupAbsolute) => {
    factorOnlyRss += groupAbsolute ** 2;
  });
  const factorAbsolute = Math.sqrt(factorOnlyRss);
  const activityAbsolute = Math.sqrt(activityOnlyRss);
  const absolute = Math.sqrt((factorAbsolute ** 2) + (activityAbsolute ** 2));
  const relative = absolute / totalKg;
  return {
    combinationMethod: 'root_sum_square',
    combinedRelativeUncertainty: Math.round(relative * 10000) / 10000,
    combinedAbsoluteUncertaintyKg: Math.round(absolute * 100) / 100,
    lowerBoundKg: Math.round((totalKg - absolute) * 100) / 100,
    upperBoundKg: Math.round((totalKg + absolute) * 100) / 100,
    confidenceLevel: 0.95,
    contributingTransactionCount: contributingCount,
    totalKg: Math.round(totalKg * 100) / 100,
    computed: true,
    components: {
      factorRelativeUncertainty: Math.round((factorAbsolute / totalKg) * 10000) / 10000,
      activityRelativeUncertainty: Math.round((activityAbsolute / totalKg) * 10000) / 10000,
      factorAbsoluteUncertaintyKg: Math.round(factorAbsolute * 100) / 100,
      activityAbsoluteUncertaintyKg: Math.round(activityAbsolute * 100) / 100
    },
    methodology: 'Factor uncertainty is fully correlated within a factor and combined by RSS across factors. Activity and OCR uncertainty is RSS across vouchers.'
  };
};

const EXTRA_SCOPE3_LABELS = Object.freeze({
  water: 'Purchased water',
  sewage: 'Sewage disposal',
  maintenance: 'Maintenance and other indirect sources',
  other: 'Other indirect sources'
});

const EXTRA_SCOPE3_ISO_PLACEMENT = Object.freeze({
  water: 'ISO 14064-1 Category 4 — Products used',
  sewage: 'ISO 14064-1 Category 4 — Products used',
  maintenance: 'ISO 14064-1 Category 6 — Other sources',
  other: 'ISO 14064-1 Category 6 — Other sources'
});

const normalizeScope3ComponentKey = (value) => {
  const key = String(value || '').trim().toLowerCase();
  if (!key || key === 'unclassified') return 'unclassified_indirect';
  if (key === 'sewage_charges') return 'sewage';
  return key;
};

/**
 * Kilograms of Scope 3 on one transaction, one entry per GHG category.
 * Compound vouchers store that split on scope3Components. A voucher with no
 * split keeps its whole Scope 3 total on the primary category.
 */
const scope3KilogramsByCategory = (transaction = {}) => {
  const footprint = transaction.carbonFootprint || {};
  const scope3 = toFinite(footprint.emissionBreakdown?.scope3, 0);
  if (scope3 <= 0) return [];

  const linkedCategory = consultantLinkedScope3Key(transaction);
  if (linkedCategory) {
    return scope3 > 0 ? [{ key: linkedCategory, kg: scope3 }] : [];
  }
  const primaryKey = normalizeScope3ComponentKey(
    footprint.ghgScope3Category || resolveScope3GhgCategory(transaction)
  );
  const components = Array.isArray(footprint.scope3Components) ? footprint.scope3Components : [];
  const parts = components
    .map((component) => ({
      key: normalizeScope3ComponentKey(component?.ghgScope3Category),
      kg: toFinite(component?.kg, 0)
    }))
    .filter((part) => part.kg > 0);

  if (!parts.length) {
    return [{ key: primaryKey, kg: scope3 }];
  }

  const assigned = parts.reduce((sum, part) => sum + part.kg, 0);
  const remainder = Math.round((scope3 - assigned) * 10000) / 10000;
  if (remainder > 0.0001) {
    parts.push({ key: primaryKey, kg: remainder });
  }
  return parts;
};

const mapScope3CategoryToEsgBreakdownKey = (ghgCategory) => {
  const map = {
    cat1_purchased_goods: 'purchasedGoods',
    cat2_capital_goods: 'purchasedGoods',
    cat3_fuel_energy_related: 'other',
    cat4_upstream_transport: 'transportation',
    cat5_waste: 'wasteDisposal',
    cat6_business_travel: 'businessTravel',
    cat7_employee_commuting: 'employeeCommuting',
    cat8_upstream_leased_assets: 'leasedAssets',
    cat9_downstream_transport: 'transportation',
    cat10_processing_sold_products: 'processingSoldProducts',
    cat11_use_sold_products: 'useSoldProducts',
    cat12_end_of_life: 'endLifeDisposal',
    cat13_downstream_leased_assets: 'leasedAssets',
    cat14_franchises: 'franchises',
    cat15_investments: 'investments',
    unclassified_indirect: 'other'
  };
  return map[ghgCategory] || 'other';
};

const aggregateInventoryMetadata = (transactions = [], options = {}) => {
  const rows = Array.isArray(transactions) ? transactions : [];
  const dataQualityMix = {
    tier_1_activity: 0,
    tier_2_spend_proxy: 0,
    tier_3_estimate: 0,
    excluded: 0
  };
  const quantificationMix = {
    activity_based: 0,
    spend_proxy: 0,
    estimate: 0,
    excluded_non_emitting_financial_flow: 0
  };
  const scope3ByCategory = {};
  GHG_SCOPE3_CATEGORY_KEYS.forEach((key) => {
    scope3ByCategory[key] = 0;
  });

  let scope1 = 0;
  let scope2Location = 0;
  let scope2Market = 0;
  let scope3 = 0;
  let grossTotal = 0;
  let biogenicCo2Kg = 0;
  let unclassifiedScope3 = 0;
  const confirmedScope3 = new Set();
  let activityCount = 0;
  let provisionalCount = 0;
  let provisionalEmittingCount = 0;
  let provisionalKg = 0;

  rows.forEach((transaction) => {
    const footprint = transaction.carbonFootprint || {};
    const co2 = toFinite(footprint.co2Emissions, 0);
    biogenicCo2Kg += toFinite(footprint.biogenicCo2Kg, 0);
    if (co2 <= 0 && !footprint.exclusionReason && !(toFinite(footprint.biogenicCo2Kg, 0) > 0)) {
      return;
    }

    const method = accountingExportParkedActivityCalculated(transaction)
      ? QUANTIFICATION_METHODS.ACTIVITY
      : (footprint.quantificationMethod || resolveQuantificationMethod(transaction));
    const tier = footprint.quantificationMethod === method && footprint.dataQualityTier
      ? footprint.dataQualityTier
      : (footprint.dataQualityTier && !accountingExportParkedActivityCalculated(transaction)
        ? footprint.dataQualityTier
        : resolveDataQualityTier(method));
    dataQualityMix[tier] = (dataQualityMix[tier] || 0) + (co2 > 0 ? co2 : 1);
    quantificationMix[method] = (quantificationMix[method] || 0) + (co2 > 0 ? co2 : 1);
    if (method === QUANTIFICATION_METHODS.ACTIVITY) {
      activityCount += 1;
    }

    if (isProvisionalInventoryTransaction(transaction)) {
      provisionalCount += 1;
      if (co2 > 0) {
        provisionalEmittingCount += 1;
        provisionalKg += co2;
      }
    }

    const breakdown = footprint.emissionBreakdown || {};
    scope1 += toFinite(breakdown.scope1, 0);
    scope2Location += toFinite(breakdown.scope2, 0);
    scope2Market += toFinite(footprint.scope2Reporting?.marketBasedKg, breakdown.scope2);
    scope3 += toFinite(breakdown.scope3, 0);
    grossTotal += co2;

    const confirmedCategory = Number(transaction.metadata?.consultantScope3Category);
    if (Number.isInteger(confirmedCategory) && confirmedCategory >= 8 && confirmedCategory <= 15 && confirmedCategory !== 9) {
      confirmedScope3.add(confirmedCategory);
    }
    scope3KilogramsByCategory(transaction).forEach((part) => {
      scope3ByCategory[part.key] = (scope3ByCategory[part.key] || 0) + part.kg;
      if (part.key === 'unclassified_indirect') {
        unclassifiedScope3 += part.kg;
      }
    });
  });

  const txnCount = rows.length;
  const emittingCount = rows.filter((t) => toFinite(t?.carbonFootprint?.co2Emissions, 0) > 0).length;
  const activitySharePct = txnCount > 0 ? Math.round((activityCount / txnCount) * 1000) / 10 : 0;
  const tier1Kg = dataQualityMix.tier_1_activity || 0;
  const tier2Kg = dataQualityMix.tier_2_spend_proxy || 0;
  const tier3Kg = dataQualityMix.tier_3_estimate || 0;
  const qualityDenom = tier1Kg + tier2Kg + tier3Kg;
  const completenessScore = Math.min(100, Math.round(
    (emittingCount > 0 ? 35 : 0)
    + Math.min(35, activitySharePct * 0.35)
    + Math.min(20, (options.documentCount || 0) > 0 ? 20 : 0)
    + Math.min(10, emittingCount >= 5 ? 10 : emittingCount * 2)
  ));

  const provisionalTransactionSharePct = txnCount > 0
    ? Math.round((provisionalCount / txnCount) * 1000) / 10
    : 0;
  const provisionalEmissionsSharePct = grossTotal > 0
    ? Math.round((provisionalKg / grossTotal) * 1000) / 10
    : 0;

  const scope3GapNote = {
    cat1_purchased_goods: 'Purchased goods need a material quantity or a supplier primary factor.',
    cat2_capital_goods: 'Capital goods need a quantity stored apart from everyday purchases.',
    cat3_fuel_energy_related: 'Fuel well-to-tank and electricity transmission loss are added when fuel or grid electricity is calculated.',
    cat4_upstream_transport: 'Upstream freight needs tonne-km or a freight quantity.',
    cat5_waste: 'Operational waste needs a mass and a waste treatment factor.',
    cat6_business_travel: 'Business travel needs passenger-km or flight airports. Hotel room-nights in India use 58.9 kgCO2e per room-night (hotel_stay_india). A stay named outside India stays at zero.',
    cat7_employee_commuting: 'Commuting needs kilometres. Home-working needs kWh. Hour-only home-working stays at zero.',
    cat8_upstream_leased_assets: 'Upstream leased assets need electricity kWh or a named fuel volume.',
    cat9_downstream_transport: 'Downstream freight needs its own transport quantity.',
    cat10_processing_sold_products: 'Processing of sold products needs processing kWh, a named fuel volume, or a primary kg figure.',
    cat11_use_sold_products: 'Use of sold products needs use-phase kWh, a named fuel volume, or a primary kg figure.',
    cat12_end_of_life: 'End-of-life treatment needs a sold-product mass or a primary kg figure.',
    cat13_downstream_leased_assets: 'Downstream leased assets need the lessee electricity kWh or a named fuel volume.',
    cat14_franchises: 'Franchises need franchisee kWh or a reported franchisee inventory.',
    cat15_investments: 'Investments need a financed-emissions figure, or an attribution share and the investee inventory.'
  };
  const scope3IsoPlacement = {
    ...EXTRA_SCOPE3_ISO_PLACEMENT,
    cat1_purchased_goods: 'ISO 14064-1 Category 4 — Products used',
    cat2_capital_goods: 'ISO 14064-1 Category 4 — Products used',
    cat3_fuel_energy_related: 'ISO 14064-1 Category 4 — Products used',
    cat4_upstream_transport: 'ISO 14064-1 Category 3 — Transportation',
    cat5_waste: 'ISO 14064-1 Category 6 — Other sources',
    cat6_business_travel: 'ISO 14064-1 Category 3 — Transportation',
    cat7_employee_commuting: 'ISO 14064-1 Category 3 — Transportation',
    cat8_upstream_leased_assets: 'ISO 14064-1 Category 6 — Other sources',
    cat9_downstream_transport: 'ISO 14064-1 Category 3 — Transportation',
    cat10_processing_sold_products: 'ISO 14064-1 Category 5 — Use of products',
    cat11_use_sold_products: 'ISO 14064-1 Category 5 — Use of products',
    cat12_end_of_life: 'ISO 14064-1 Category 6 — Other sources',
    cat13_downstream_leased_assets: 'ISO 14064-1 Category 6 — Other sources',
    cat14_franchises: 'ISO 14064-1 Category 6 — Other sources',
    cat15_investments: 'ISO 14064-1 Category 6 — Other sources',
    unclassified_indirect: 'Unallocated — no share is invented'
  };
  const categoryOrder = (key) => {
    const match = String(key).match(/^cat(\d+)/);
    return match ? Number(match[1]) : 99;
  };
  const scope3CategoryRows = GHG_SCOPE3_CATEGORY_KEYS
    .filter((key) => key !== 'unclassified_indirect')
    .map((key) => {
      const kg = scope3ByCategory[key] || 0;
      return {
        key,
        label: GHG_SCOPE3_LABELS[key] || key,
        kgCO2e: Math.round(kg * 100) / 100,
        sharePercent: scope3 > 0 ? Math.round((kg / scope3) * 1000) / 10 : 0,
        status: kg > 0 ? 'quantified' : 'not_quantified',
        gap: kg > 0 ? null : (scope3GapNote[key] || null),
        isoPlacement: scope3IsoPlacement[key] || null
      };
    })
    .sort((a, b) => b.kgCO2e - a.kgCO2e || categoryOrder(a.key) - categoryOrder(b.key));
  Object.keys(scope3ByCategory)
    .filter((key) => !GHG_SCOPE3_CATEGORY_KEYS.includes(key) && (scope3ByCategory[key] || 0) > 0)
    .forEach((key) => {
      const kg = scope3ByCategory[key];
      scope3CategoryRows.push({
        key,
        label: EXTRA_SCOPE3_LABELS[key] || GHG_SCOPE3_LABELS[key] || key,
        kgCO2e: Math.round(kg * 100) / 100,
        sharePercent: scope3 > 0 ? Math.round((kg / scope3) * 1000) / 10 : 0,
        status: 'quantified',
        gap: null,
        isoPlacement: scope3IsoPlacement[key] || null
      });
    });
  scope3CategoryRows.sort((a, b) => b.kgCO2e - a.kgCO2e || categoryOrder(a.key) - categoryOrder(b.key));
  if ((scope3ByCategory.unclassified_indirect || 0) > 0) {
    const kg = scope3ByCategory.unclassified_indirect;
    scope3CategoryRows.push({
      key: 'unclassified_indirect',
      label: GHG_SCOPE3_LABELS.unclassified_indirect || 'unclassified_indirect',
      kgCO2e: Math.round(kg * 100) / 100,
      sharePercent: scope3 > 0 ? Math.round((kg / scope3) * 1000) / 10 : 0,
      status: 'unallocated',
      gap: 'These kilograms stay unallocated until a Scope 3 category is stored.',
      isoPlacement: scope3IsoPlacement.unclassified_indirect
    });
  }

  const combinedUncertainty = computeCombinedInventoryUncertainty(rows);
  const hasMarketInstruments = rows.some((t) => {
    const instruments = t.marketBasedInstruments
      || t.sustainability?.marketBasedInstruments
      || t.carbonFootprint?.scope2Reporting?.instruments
      || [];
    return Array.isArray(instruments) && instruments.length > 0;
  });

  return {
    methodology: CARBON_SHARED.reportingLabel || 'CO2e_activity_and_spend_proxy',
    methodologyNote: CARBON_SHARED.methodologyNote,
    organizationalBoundary: {
      ...ORGANIZATIONAL_BOUNDARY_DEFAULT,
      ...(options.organizationalBoundary || {})
    },
    dataQualityMix,
    quantificationMix,
    dataQualitySummary: {
      activitySharePct,
      tier1SharePct: qualityDenom > 0 ? Math.round((tier1Kg / qualityDenom) * 1000) / 10 : 0,
      tier2SharePct: qualityDenom > 0 ? Math.round((tier2Kg / qualityDenom) * 1000) / 10 : 0,
      tier3SharePct: qualityDenom > 0 ? Math.round((tier3Kg / qualityDenom) * 1000) / 10 : 0
    },
    scopeTotals: {
      scope1: Math.round(scope1 * 100) / 100,
      scope2LocationBased: Math.round(scope2Location * 100) / 100,
      scope2MarketBased: Math.round(scope2Market * 100) / 100,
      scope3: Math.round(scope3 * 100) / 100,
      grossTotal: Math.round(grossTotal * 100) / 100,
      biogenicCo2Kg: Math.round(biogenicCo2Kg * 100) / 100,
      biogenicCo2Reporting: biogenicCo2Kg > 0 ? 'reported_separately' : null
    },
    scope2DualReporting: {
      locationBasedKg: Math.round(scope2Location * 100) / 100,
      marketBasedKg: Math.round(scope2Market * 100) / 100,
      deltaKg: Math.round((scope2Location - scope2Market) * 100) / 100,
      dualTotalsAvailable: scope2Location > 0,
      marketInstrumentsPresent: hasMarketInstruments
        || Boolean(options.boundary?.scope2MarketBased)
        || Boolean(options.scope2MarketBased)
    },
    combinedUncertainty,
    scope3ByCategory: scope3CategoryRows,
    consultantConfirmedScope3: [...confirmedScope3].sort((left, right) => left - right),
    unclassifiedScope3Kg: Math.round(unclassifiedScope3 * 100) / 100,
    completenessScore,
    transactionCount: txnCount,
    emittingTransactionCount: emittingCount,
    inventoryVerificationSummary: {
      provisionalTransactionCount: provisionalCount,
      provisionalEmittingTransactionCount: provisionalEmittingCount,
      provisionalEmissionsKg: Math.round(provisionalKg * 100) / 100,
      provisionalTransactionSharePct,
      provisionalEmissionsSharePct,
      hasProvisionalInventory: provisionalCount > 0,
      statutoryReportingNote: provisionalCount > 0
        ? 'Inventory includes provisional OCR-derived transactions pending bill verification.'
        : null
    },
    configVersion: CARBON_SHARED.configVersion
  };
};

const buildTransactionInventoryFields = (transaction = {}, footprint = {}) => {
  const category = transaction.category || 'other';
  const quantificationMethod = footprint.quantificationMethod
    || resolveQuantificationMethod(transaction, category);
  const ghgScope3Category = footprint.ghgScope3Category || resolveScope3GhgCategory(transaction);
  const resolvedLineage = footprint.factorLineage
    || resolveFactorLineage(transaction, category, transaction.subcategory);
  const factorLineage = resolvedLineage || {
    id: 'no_factor_applied',
    factor: 0,
    unit: 'kgCO2e',
    source: 'No factor applied',
    sourceDocument: 'GHG Protocol — no combustion or activity factor was applied',
    geography: 'India',
    relativeUncertainty: 0,
    quantificationMethod
  };
  const activity = extractActivityQuantity(transaction);
  const factorRelativeUncertainty = toFinite(factorLineage.relativeUncertainty, 0.25);
  const activityRelativeUncertainty = resolveActivityRelativeUncertainty(transaction, {
    ...footprint,
    quantificationMethod
  });
  const relativeUncertainty = combineFactorAndActivityRelativeUncertainty(
    factorRelativeUncertainty,
    activityRelativeUncertainty
  );
  const co2 = toFinite(footprint.co2Emissions, 0);

  const assuranceGrade = isAssuranceGradeLineage(factorLineage);
  // Measured activity keeps its activity tier. assuranceGrade stays false for a
  // screening or non-assurance factor and does not relabel the quantity.
  const dataQualityTier = resolveDataQualityTier(quantificationMethod);

  return {
    quantificationMethod,
    dataQualityTier,
    assuranceGrade,
    ghgScope3Category,
    ghgScope3Label: GHG_SCOPE3_LABELS[ghgScope3Category],
    esgScope3BreakdownKey: mapScope3CategoryToEsgBreakdownKey(ghgScope3Category),
    activityRelativeUncertainty,
    combinedRelativeUncertainty: relativeUncertainty,
    factorLineage: {
      ...factorLineage,
      relativeUncertainty: factorRelativeUncertainty,
      activityRelativeUncertainty,
      combinedRelativeUncertainty: relativeUncertainty,
      lowerBoundKg: Math.round(co2 * (1 - relativeUncertainty) * 10000) / 10000,
      upperBoundKg: Math.round(co2 * (1 + relativeUncertainty) * 10000) / 10000,
      confidenceLevel: 0.95
    },
    activityQuantity: activity.quantity > 0 ? activity.quantity : null,
    activityUnit: activity.unit,
    scope2Reporting: footprint.scope2Reporting
      || (toFinite(footprint.emissionBreakdown?.scope2, 0) > 0
        ? (() => {
          const { buildScope2DualReportWithInstruments } = require('./ghgInventoryGovernance');
          return buildScope2DualReportWithInstruments(
            transaction,
            footprint.emissionBreakdown.scope2
          );
        })()
        : null)
  };
};

