/**
 * Classifies a transaction for consultant review and decides whether a
 * statutory report may be generated.
 *
 * Required review: rows with no calculation, and spend-based rows.
 * Optional review: rows that already have an activity or supplier calculation,
 * when the company sets consultantReviewScope to "all".
 * A confirmation stays valid only while the calculation fingerprint matches.
 */

const REVIEW_STATUSES = new Set(['confirmed', 'corrected']);

const flagText = (flags) => {
  if (Array.isArray(flags)) return flags.filter(Boolean).join(';');
  if (flags && typeof flags === 'object') {
    return Object.entries(flags)
      .filter(([, on]) => Boolean(on))
      .map(([key]) => key)
      .join(';');
  }
  return String(flags || '');
};

const calculationView = (transaction = {}) => {
  const footprint = transaction.carbonFootprint && typeof transaction.carbonFootprint === 'object'
    ? transaction.carbonFootprint
    : transaction;
  const record = footprint.calculationRecord || {};
  const review = transaction.metadata?.consultantReview || transaction.consultantReview || null;
  return {
    quantificationMethod: footprint.quantificationMethod || footprint.calculationMethod || '',
    dataQualityTier: footprint.dataQualityTier || '',
    formula: record.formula || footprint.formula || '',
    complianceFlags: footprint.complianceFlags,
    exclusionReason: footprint.exclusionReason || transaction.exclusionReason || '',
    factorId: footprint.factorLineage?.id || footprint.factorId || '',
    co2Emissions: Number(footprint.co2Emissions || 0),
    category: transaction.category || '',
    quantity: transaction.quantity,
    unit: transaction.unit || '',
    consultantReview: review,
    isSpam: transaction.isSpam === true,
    isDuplicate: transaction.isDuplicate === true
  };
};

const classifyCalculation = (transaction) => {
  const view = calculationView(transaction);
  if (view.isSpam || view.isDuplicate) return 'excluded';

  const method = String(view.quantificationMethod).toLowerCase();
  const tier = String(view.dataQualityTier).toLowerCase();
  const formula = String(view.formula);
  const flags = flagText(view.complianceFlags);
  const factorId = String(view.factorId);

  if (method.includes('supplier')) return 'calculated';
  if (method.includes('excluded') || tier === 'excluded' || view.exclusionReason) return 'excluded';

  const needsExpert = method.includes('admin_emission_review')
    || formula === 'adminEmissionReview'
    || flags.includes('admin_emission_review_required');
  const missingActivity = method.includes('needs_activity')
    || /_missing\b/i.test(flags)
    || /_missing\b/i.test(factorId);
  const notStated = !method && !formula && !tier;
  const spend = method.includes('spend') || tier.includes('tier_2') || formula.includes('spendAmount');
  const activity = method.includes('activity')
    || formula.startsWith('activityQuantity')
    || tier.includes('tier_1');

  if (needsExpert || missingActivity || notStated) return 'without_calculation';
  if (spend) return 'spend_based';
  if (activity) return 'calculated';
  return 'without_calculation';
};

const CALCULATION_CLASS_LABELS = {
  without_calculation: 'Without calculation',
  spend_based: 'Spend-based',
  calculated: 'With calculation',
  excluded: 'Excluded'
};

const calculationClassLabel = (calculationClass) => (
  CALCULATION_CLASS_LABELS[calculationClass] || 'Without calculation'
);

const UNVERIFIED_LINEAGE_IDS = new Set([
  'activity_classification_required',
  'spend_generic',
  'unspecified_fuel_type',
  'material_factor_unspecified',
  'fuel_factor_unspecified',
  'refrigerant_species_unspecified',
  'service_hour_factor_unspecified',
  'activity_unit_not_converted'
]);

const legacyFingerprint = (transaction) => {
  const view = calculationView(transaction);
  const calculationClass = classifyCalculation(transaction);
  const quantity = view.quantity == null || view.quantity === '' ? '' : String(view.quantity);
  const co2 = Number.isFinite(view.co2Emissions) ? view.co2Emissions.toFixed(4) : '0.0000';
  return [
    calculationClass,
    view.quantificationMethod,
    view.formula,
    co2,
    view.category,
    quantity,
    view.unit
  ].join('|');
};

const lineageEstablished = (transaction) => {
  const lineage = transaction?.carbonFootprint?.factorLineage || {};
  const factorId = String(lineage.id || '');
  const factor = Number(lineage.factor);
  if (!factorId || UNVERIFIED_LINEAGE_IDS.has(factorId) || /_missing\b/i.test(factorId)) return false;
  if (!Number.isFinite(factor)) return false;
  return Boolean(String(lineage.sourceVersion || '').trim());
};

const sameText = (left, right) => String(left ?? '') === String(right ?? '');

const sameNumber = (left, right) => {
  const a = Number(left);
  const b = Number(right);
  if (!Number.isFinite(a) || !Number.isFinite(b)) return false;
  return Math.abs(a - b) < 1e-9;
};

/**
 * A legacy stamp matches only when the approved decision snapshot records the
 * same factor id, factor value, factor unit, sourceVersion, CO2, formula,
 * method, category, quantity, and unit as the stored calculation.
 * A real factor id and sourceVersion on the current row are not that proof.
 * A missing snapshot is not a match. v2 fingerprints do not use this path.
 */
const legacyApprovalMatches = (transaction, snapshot) => {
  if (!snapshot || typeof snapshot !== 'object') return false;
  const lineage = transaction?.carbonFootprint?.factorLineage || {};
  const footprint = transaction?.carbonFootprint || {};
  if (!String(snapshot.factorId || '').trim()) return false;
  if (!String(snapshot.sourceVersion || '').trim()) return false;
  if (!Number.isFinite(Number(snapshot.factor))) return false;
  if (!sameText(snapshot.factorId, lineage.id)) return false;
  if (!sameNumber(snapshot.factor, lineage.factor)) return false;
  if (!sameText(snapshot.factorUnit, lineage.unit)) return false;
  if (!sameText(snapshot.sourceVersion, lineage.sourceVersion)) return false;
  if (!sameNumber(snapshot.co2Kg, footprint.co2Emissions || 0)) return false;
  if (!sameText(snapshot.formula, footprint.calculationRecord?.formula || footprint.formula || '')) return false;
  if (!sameText(snapshot.method, footprint.quantificationMethod || footprint.calculationMethod || '')) return false;
  if (!sameText(snapshot.category, transaction?.category || '')) return false;
  if (!sameText(snapshot.unit, transaction?.unit || '')) return false;
  const approvedQuantity = snapshot.quantity == null || snapshot.quantity === '' ? '' : String(snapshot.quantity);
  const currentQuantity = transaction?.quantity == null || transaction.quantity === '' ? '' : String(transaction.quantity);
  return approvedQuantity === currentQuantity;
};

/**
 * Calculated rows whose stored lineage is a sentinel, a blank id, a zero
 * result without a methodology source, or a numbered factor without a
 * sourceVersion cannot enter an official report.
 * A row with no factorLineage object keeps the closed Phase 1 activity rule.
 * Spend-based and without-calculation rows stay on the consultant gate.
 * A real zero factor with a methodology source stays eligible.
 */
const reportLineageBlocksOfficialReport = (transaction = {}) => {
  if (classifyCalculation(transaction) !== 'calculated') return false;
  const lineage = transaction?.carbonFootprint?.factorLineage;
  if (!lineage || typeof lineage !== 'object') return false;
  const factorId = String(lineage.id || '').trim();
  const factor = Number(lineage.factor);
  const source = String(lineage.source || '').trim();
  const sourceVersion = String(lineage.sourceVersion || '').trim();
  const sentinel = !factorId || UNVERIFIED_LINEAGE_IDS.has(factorId) || /_missing\b/i.test(factorId);
  if (!sentinel && factor === 0 && source) return false;
  if (sentinel) return true;
  if ((Number.isFinite(factor) || source) && !sourceVersion) return true;
  return false;
};

const calculationFingerprint = (transaction) => {
  const lineage = transaction?.carbonFootprint?.factorLineage || {};
  const factor = Number(lineage.factor);
  return [
    'v2',
    legacyFingerprint(transaction),
    String(lineage.id || ''),
    Number.isFinite(factor) ? factor.toFixed(6) : '',
    String(lineage.unit || ''),
    String(lineage.sourceVersion || '')
  ].join('|');
};

const reviewIsCurrent = (transaction) => {
  const review = calculationView(transaction).consultantReview;
  if (!review || !REVIEW_STATUSES.has(String(review.status || ''))) return false;
  const stored = String(review.fingerprint || '');
  if (!stored) return false;
  if (stored.startsWith('v2|')) return stored === calculationFingerprint(transaction);
  if (stored !== legacyFingerprint(transaction)) return false;
  return legacyApprovalMatches(transaction, transaction?.approvedCalculation);
};

const emptyCounts = () => ({
  withoutCalculation: 0,
  spendBased: 0,
  calculated: 0,
  excluded: 0
});

const normalizeScope = (scope) => (scope === 'all' ? 'all' : 'required');

/**
 * One row contributes to summary.openRequired.
 * Excluded rows never count. A current confirmed or corrected review never counts.
 * Calculated rows count only when the normalized scope is all.
 * Every other non-excluded class counts while the review is not current.
 */
const countsTowardOpenRequired = (transaction, scope = 'required') => {
  const calculationClass = classifyCalculation(transaction);
  if (calculationClass === 'excluded') return false;
  if (reviewIsCurrent(transaction)) return false;
  if (calculationClass === 'calculated') return normalizeScope(scope) === 'all';
  return true;
};

const summarizeConsultantReview = (transactions, scope = 'required') => {
  const counts = emptyCounts();
  const open = {
    withoutCalculation: 0,
    spendBased: 0,
    calculated: 0
  };
  let openRequired = 0;

  (transactions || []).forEach((transaction) => {
    const calculationClass = classifyCalculation(transaction);
    if (calculationClass === 'excluded') {
      counts.excluded += 1;
      return;
    }
    if (calculationClass === 'spend_based') counts.spendBased += 1;
    else if (calculationClass === 'calculated') counts.calculated += 1;
    else counts.withoutCalculation += 1;

    if (reviewIsCurrent(transaction)) return;
    if (calculationClass === 'spend_based') open.spendBased += 1;
    else if (calculationClass === 'calculated') open.calculated += 1;
    else open.withoutCalculation += 1;
    if (countsTowardOpenRequired(transaction, scope)) openRequired += 1;
  });

  const normalizedScope = normalizeScope(scope);

  return {
    scope: normalizedScope,
    counts,
    open,
    openRequired,
    ready: openRequired === 0
  };
};

const blocksReport = (calculationClass, scope) => {
  if (calculationClass === 'excluded') return false;
  if (calculationClass === 'calculated') return normalizeScope(scope) === 'all';
  return calculationClass === 'without_calculation' || calculationClass === 'spend_based';
};

const csvSummaryLines = (summary) => ([
  'Consultant review summary',
  `Without calculation,${summary.counts.withoutCalculation}`,
  `Spend-based,${summary.counts.spendBased}`,
  `With calculation,${summary.counts.calculated}`,
  `Excluded,${summary.counts.excluded}`,
  `Still open without calculation,${summary.open.withoutCalculation}`,
  `Still open spend-based,${summary.open.spendBased}`,
  `Still open with calculation,${summary.open.calculated}`,
  ''
]);

const blockMessage = (summary) => {
  if (summary?.reason === 'factor_lineage') {
    const count = Number(summary.factorLineageCount || 0);
    return `${count} transaction${count === 1 ? '' : 's'} ${count === 1 ? 'has a stored emission factor that cannot' : 'have stored emission factors that cannot'} be used in an official report.`;
  }
  if (summary?.reason === 'factor_exception') {
    const count = Number(summary.factorExceptionCount || 0);
    return `${count} transaction${count === 1 ? '' : 's'} still ${count === 1 ? 'has' : 'have'} an unresolved emission factor exception. An official report stays closed until an expert resolves each one.`;
  }
  const parts = [];
  if (summary.open.withoutCalculation) {
    parts.push(`${summary.open.withoutCalculation} without a calculation`);
  }
  if (summary.open.spendBased) {
    parts.push(`${summary.open.spendBased} spend-based`);
  }
  if (summary.scope === 'all' && summary.open.calculated) {
    parts.push(`${summary.open.calculated} with a calculation`);
  }
  const list = parts.length ? parts.join(', ') : 'the open rows';
  return `An expert consultant still has to review ${list} before this report can be generated.`;
};

module.exports = {
  CALCULATION_CLASS_LABELS,
  blockMessage,
  blocksReport,
  calculationClassLabel,
  calculationFingerprint,
  legacyApprovalMatches,
  legacyFingerprint,
  lineageEstablished,
  reportLineageBlocksOfficialReport,
  classifyCalculation,
  countsTowardOpenRequired,
  csvSummaryLines,
  reviewIsCurrent,
  summarizeConsultantReview
};
