import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Paper,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

interface SubmissionCounts {
  total: number;
  approved: number;
  pending: number;
  waitingForBill: number;
  additionalInformation: number;
  failed: number;
  excluded?: number;
  clarificationAnswered?: number;
  clarificationAnsweredCount?: number;
  excludedCount?: number;
}

interface SubmissionRow {
  batchId: string;
  status: string;
  message: string;
  source: string;
  fileName?: string;
  provider?: string;
  submittedAt?: string;
  counts: SubmissionCounts;
}

const token = () => localStorage.getItem('token');

const countLine = (counts: SubmissionCounts) => {
  const answered = counts.clarificationAnsweredCount ?? counts.clarificationAnswered ?? 0;
  const excluded = counts.excludedCount ?? counts.excluded ?? 0;
  return `Status uses the server counts. Total ${counts.total}. Approved ${counts.approved}. Pending ${counts.pending}. Clarification open ${counts.additionalInformation}. Clarification answered ${answered}. Bill required ${counts.waitingForBill}. Failed ${counts.failed}. Excluded ${excluded}.`;
};

const ExpertApprovalSubmissions: React.FC<{ onUnresolvedChange?: (unresolved: boolean) => void }> = ({ onUnresolvedChange }) => {
  const [rows, setRows] = useState<SubmissionRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [provisional, setProvisional] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!token()) {
      setRows([]);
      setLoading(false);
      onUnresolvedChange?.(false);
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert-approval/submissions'), {
        headers: { Authorization: `Bearer ${token()}` },
      });
      const page = response.data?.data?.submissions || [];
      setRows(page);
      onUnresolvedChange?.(page.some((row: SubmissionRow) => row.status !== 'Approved'));
    } catch (loadError: any) {
      if (loadError?.response?.status === 403) {
        setRows([]);
        onUnresolvedChange?.(false);
      } else {
        setError(loadError?.response?.data?.message || 'Submissions could not be loaded.');
      }
    } finally {
      setLoading(false);
    }
  }, [onUnresolvedChange]);

  useEffect(() => {
    void load();
  }, [load]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
        <CircularProgress size={18} />
        <Typography variant="body2">Loading submissions...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 2 }} action={<Button color="inherit" size="small" onClick={() => void load()}>Retry</Button>}>
        {error}
      </Alert>
    );
  }

  if (rows.length === 0) return null;

  return (
    <Paper variant="outlined" sx={{ p: 2, mb: 2 }}>
      <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
        Expert approval submissions
      </Typography>
      <Button size="small" sx={{ mb: 1 }} onClick={async () => {
        setProvisional(null);
        setError(null);
        try {
          const response = await axios.get(buildApiUrl('/expert-approval/provisional-report'), {
            headers: { Authorization: `Bearer ${token()}` },
          });
          const report = response.data?.data;
          setProvisional(report?.warning
            ? `${report.warning} Included ${report.includedCount}. Excluded ${report.excludedCount}.`
            : 'Provisional report could not be read.');
        } catch (loadError: any) {
          setError(loadError?.response?.data?.message || 'The provisional report could not be loaded.');
        }
      }}
      >
        View provisional internal report
      </Button>
      {provisional ? <Alert severity="warning" sx={{ mb: 1 }}>{provisional}</Alert> : null}
      {rows.map((row) => (
        <Box key={row.batchId} sx={{ py: 1, borderTop: '1px solid', borderColor: 'divider' }}>
          <Typography variant="body2" sx={{ fontWeight: 700 }}>
            {row.fileName || row.provider || (row.source === 'connector' ? 'Data Connector' : 'Excel import')}
          </Typography>
          <Typography variant="body2">{row.message}</Typography>
          <Typography variant="caption" color="text.secondary" display="block">
            {`${row.source === 'connector' ? 'Data Connector' : 'Excel'} · ${row.submittedAt ? new Date(row.submittedAt).toLocaleString() : 'Date unavailable'} · Batch ${row.batchId}`}
          </Typography>
          <Typography variant="caption" color="text.secondary" display="block">
            {`Status ${row.status}. ${countLine(row.counts)} Some approved rows do not make this submission complete.`}
          </Typography>
        </Box>
      ))}
    </Paper>
  );
};

export default ExpertApprovalSubmissions;
