/**
 * Published rupee prices for spend-proxy quantity.
 * Quantity = pre-tax spend ÷ price. Emissions = quantity × the factor
 * whose activity unit is the same as the price unit.
 * A price is not applied when the published unit and the factor unit differ.
 */

const { normalizeUnit } = require('./carbonEmissionAnalytics');

const TWO_WHEELER_PETROL_INR_PER_LITRE = 102.12;
const TWO_WHEELER_KM_PER_LITRE = 44.5;
const CEMENT_BAG_INR = 361;
const CEMENT_BAG_KG = 50;

const price = (entry) => Object.freeze(entry);

const CITED_SPEND_PROXY_PRICES = Object.freeze({
  transport_road_tonkm: price({
    factorId: 'transport_road_tonkm',
    priceInr: 3.78,
    activityUnit: 'tonne-km',
    citation: 'DPIIT and NCAER, Assessment of Logistics Cost in India, reference year 2023-24: road average ₹3.78 per tonne-km. Light trucks are ₹11.03 and 55 t trailers are ₹1.51; the unnamed road-freight row uses the road average. https://www.dpiit.gov.in/static/uploads/2025/09/c0d7c33f0b737ed71728ff6c2a35f1e7.pdf'
  }),
  transport_rail_tonkm: price({
    factorId: 'transport_rail_tonkm',
    priceInr: 1.7031,
    activityUnit: 'tonne-km',
    citation: 'Indian Railways Year Book 2023-24: average rate charged per net tonne-kilometre 170.31 paise, which is ₹1.7031 per tonne-km. This is the railway freight rate, not the DPIIT door-to-terminal logistics cost of ₹1.96 per tonne-km. https://nfr.indianrailways.gov.in/railwayboard/uploads/directorate/stat_econ/2025/IR%20Year%20Book%202023-24-English.pdf'
  }),
  travel_rail_km: price({
    factorId: 'travel_rail_km',
    priceInr: 0.664,
    activityUnit: 'km',
    citation: 'Indian Railways Year Book 2023-24: average rate charged per passenger-kilometre 66.40 paise, which is ₹0.664. A client rail ticket is one passenger, so one kilometre is one passenger-kilometre. https://nfr.indianrailways.gov.in/railwayboard/uploads/directorate/stat_econ/2025/IR%20Year%20Book%202023-24-English.pdf'
  }),
  transport_courier_kg: price({
    factorId: 'transport_courier_kg',
    priceInr: 90,
    activityUnit: 'kg',
    citation: 'India Post domestic parcel, Gazette of India S.O. 4241(E) dated 31 July 2026, effective 1 August 2026: every additional 1 kg to other states is ₹90, GST extra. This is the marginal inter-state kilogram, not a blended tariff for the first 5 kg. https://www.indiapost.gov.in/mailproducts/domesticservices/indiapostparcel'
  }),
  travel_car_km: price({
    factorId: 'travel_car_km',
    priceInr: 24,
    activityUnit: 'km',
    citation: 'Karnataka government notification of 3 February 2024 for Bengaluru cabs: vehicles valued up to ₹10 lakh are ₹24 per kilometre after the first 4 km. The ₹100 minimum for those first 4 km is not added on top of this per-kilometre rate.'
  }),
  travel_bus_pkm: price({
    factorId: 'travel_bus_pkm',
    priceInr: 0.93,
    activityUnit: 'passenger-km',
    citation: 'Karnataka government bus-fare revision effective 5 January 2025: ordinary state-transport fare stated at 93 paise per kilometre after the 15 percent hike. A bus ticket is one passenger, so the fare is applied per passenger-kilometre. https://daijiworld.com/news/newsDisplay?newsID=1259461'
  }),
  hotel_stay_india: price({
    factorId: 'hotel_stay_india',
    priceInr: 7951,
    activityUnit: 'room-night',
    citation: 'Horwath HTL India Hotel Market Report 2024, CoStar: all-India average daily rate for calendar 2024 is ₹7,951 per occupied room-night. The room-night emission factor uses the same occupied-room unit. https://horwathhtl.com/wp-content/uploads/2025/02/India-Hotel-Market-Report-2024.pdf'
  }),
  travel_two_wheeler_km: price({
    factorId: 'travel_two_wheeler_km',
    priceInr: TWO_WHEELER_PETROL_INR_PER_LITRE / TWO_WHEELER_KM_PER_LITRE,
    activityUnit: 'km',
    citation: 'Fuel cost per kilometre is the PPAC Delhi petrol retail selling price of ₹102.12 per litre on 13 August 2026 divided by 44.5 km per litre. The National Transport Development Policy Committee, Moving India to 2032, reports motorcycle fuel efficiency of 44.5 km per litre, as cited by the India GHG Program 2015 road-transport paper. https://ppac.gov.in/home'
  }),
  process_cement_calcination: price({
    factorId: 'process_cement_calcination',
    priceInr: CEMENT_BAG_INR / CEMENT_BAG_KG,
    activityUnit: 'kg',
    citation: 'Prabhudas Lilladher cement dealer survey, all-India average trade price ₹361 per 50 kg bag at June 2025, which is ₹7.22 per kg. No separate government clinker tariff is published, so the ordinary Portland cement bag price is the rupee-per-kilogram divisor. The emission factor remains IPCC clinker calcination, 0.52 kgCO2e/kg. https://www.plindia.com/ResReport/Cement-30-6-25-PL.pdf'
  })
});

const SEA_PRICE_UNIT_MISMATCH = 'Coastal shipping in the DPIIT–NCAER 2023-24 logistics assessment is ₹1.80 per tonne-km. The sea factor is kgCO2e per tonne. Those units are not divided.';

const parkedUnit = (transaction = {}) => {
  const raw = String(transaction.metadata?.importedActivity?.unit || '')
    .toLowerCase()
    .trim()
    .replace(/[\s_]+/g, '-');
  if (['tonne-km', 'ton-km', 'tonkm', 't-km', 'tkm'].includes(raw)) return 'tonne-km';
  if (['passenger-km', 'passenger-kilometre', 'pkm'].includes(raw)) return 'passenger-km';
  if (['km', 'kilometer', 'kilometre', 'kilometers', 'kilometres'].includes(raw)) return 'km';
  if (['kg', 'kilogram', 'kilograms'].includes(raw)) return 'kg';
  if (['tonne', 'tonnes', 'ton', 'mt'].includes(raw)) return 'tonne';
  if (['night', 'nights', 'room-night', 'room-nights'].includes(raw)) return 'night';
  return raw;
};

/**
 * Match an accounting-export description to one cited price.
 * Returns null when no published price matches.
 * Returns { mismatch: true } when a price exists but its unit is not the factor unit.
 */
const resolveCitedSpendProxyActivity = (transaction = {}) => {
  const category = String(transaction.category || '').toLowerCase();
  const subcategory = String(transaction.subcategory || '').toLowerCase();
  const text = `${transaction.description || ''} ${transaction.memo || ''} ${transaction.narration || ''} ${subcategory}`.toLowerCase();
  const unit = parkedUnit(transaction);

  if (category === 'revenue' || subcategory === 'sales' || /\bsales invoice\b/.test(text)) {
    return null;
  }

  if (subcategory === 'sea' || /\bsea freight\b|\bocean freight\b|\bby sea\b/.test(text)) {
    return {
      mismatch: true,
      flag: 'spend_proxy_price_unit_mismatch',
      citation: SEA_PRICE_UNIT_MISMATCH
    };
  }

  if (/\b(clinker|calcination)\b/.test(text)) {
    return { ...CITED_SPEND_PROXY_PRICES.process_cement_calcination };
  }

  if (subcategory === 'courier' || /\b(courier|parcel)\b/.test(text)) {
    return { ...CITED_SPEND_PROXY_PRICES.transport_courier_kg };
  }

  if (subcategory === 'hotel' || /\b(hotel|lodging|accommodation)\b/.test(text)) {
    return { ...CITED_SPEND_PROXY_PRICES.hotel_stay_india };
  }

  if (subcategory === 'taxi' || /\b(taxi|cab)\b/.test(text)) {
    return { ...CITED_SPEND_PROXY_PRICES.travel_car_km };
  }

  if (subcategory === 'bus' || /\bbus\b/.test(text)) {
    return { ...CITED_SPEND_PROXY_PRICES.travel_bus_pkm };
  }

  if (/\b(two-wheeler|two wheeler|motorcycle|scooter)\b/.test(text)) {
    return { ...CITED_SPEND_PROXY_PRICES.travel_two_wheeler_km };
  }

  const rail = subcategory === 'rail' || /\brail\b|\btrain\b/.test(text);
  const freight = unit === 'tonne-km' || /\b(freight|coils)\b/.test(text);
  const passenger = unit === 'km' || unit === 'passenger-km' || /\b(ticket|passenger)\b/.test(text);
  if (rail && freight && unit !== 'km' && unit !== 'passenger-km') {
    return { ...CITED_SPEND_PROXY_PRICES.transport_rail_tonkm };
  }
  if (rail && passenger) {
    return { ...CITED_SPEND_PROXY_PRICES.travel_rail_km };
  }

  if (
    category === 'transportation'
    && (unit === 'tonne-km' || subcategory === 'freight_logistics' || /\b(freight|truck|delivery)\b/.test(text))
  ) {
    return { ...CITED_SPEND_PROXY_PRICES.transport_road_tonkm };
  }

  return null;
};

const citedSpendProxyNeedsRefresh = (transaction = {}) => {
  const imported = transaction.metadata?.importedActivity;
  const importedQty = Number(imported?.quantity);
  const hasSheetQuantity = Number.isFinite(importedQty) && importedQty > 0 && imported?.unit;
  if (hasSheetQuantity) {
    const stored = transaction.carbonFootprint && typeof transaction.carbonFootprint === 'object'
      ? transaction.carbonFootprint
      : {};
    if (transaction.excludeFromCarbonFootprint === true || stored.exclusionReason) return false;
    // Parked service units are not a physical activity. The same exclusion is
    // the first check in accountingExportParkedActivityCalculated.
    if (normalizeUnit(imported.unit) === 'service_unit') return false;
    const storedQty = Number(stored.activityQuantity ?? stored.resolvedActivityQuantity);
    const method = String(stored.quantificationMethod || stored.calculationMethod || '');
    if (method === 'activity_based' && Math.abs(storedQty - importedQty) < 0.001) return false;
    if (method === 'needs_activity') return false;
    return true;
  }
  const origin = String(transaction.metadata?.quantificationOrigin || '');
  const basis = String(transaction.metadata?.carbonInputBasis || '').toLowerCase();
  if (origin !== 'accounting_export' || basis === 'activity') return false;
  if (Number(transaction.quantity) > 0) return false;
  const match = resolveCitedSpendProxyActivity(transaction);
  if (!(match?.priceInr > 0)) return false;
  const stored = transaction.carbonFootprint && typeof transaction.carbonFootprint === 'object'
    ? transaction.carbonFootprint
    : {};
  const sameFactor = String(stored.factorLineage?.id || '') === match.factorId;
  const samePrice = Math.abs(Number(stored.resolvedUnitPriceInr) - match.priceInr) < 1e-6;
  const formula = String(stored.calculationRecord?.formula || '');
  return !(
    sameFactor
    && samePrice
    && formula === '(spendAmount / unitPrice) * emissionFactor'
    && Number(stored.co2Emissions) > 0
  );
};

module.exports = {
  CITED_SPEND_PROXY_PRICES,
  SEA_PRICE_UNIT_MISMATCH,
  TWO_WHEELER_PETROL_INR_PER_LITRE,
  TWO_WHEELER_KM_PER_LITRE,
  resolveCitedSpendProxyActivity,
  citedSpendProxyNeedsRefresh
};
