/**
 * Canonical emission factor registry for backend, mobile sync, and MongoDB seeding.
 */
const REGISTRY_DOC = require('./emissionFactorRegistry.json');
const CARBON_SHARED = require('./carbonEmissionDefaults.json');

const freezeRegistryEntries = () => {
  const version = REGISTRY_DOC.registryVersion || CARBON_SHARED.configVersion || '2026-05-28';
  const entries = {};
  Object.entries(REGISTRY_DOC.factors || {}).forEach(([key, row]) => {
    entries[key] = Object.freeze({
      ...row,
      sourceVersion: row.sourceVersion || version
    });
  });
  return Object.freeze(entries);
};

const DEFAULT_FACTOR_REGISTRY = freezeRegistryEntries();

const getActivityEmissionFactors = () => {
  const tree = REGISTRY_DOC.activityTree || {};
  return {
    electricity: { ...(tree.electricity || {}) },
    fuel: { ...(tree.fuel || {}) },
    water: tree.water ?? 0.0004,
    sewage: tree.sewage ?? 0.0005,
    wastewater: tree.wastewater ?? 0.001,
    solidWaste: tree.solidWaste ?? 0.5,
    hazardousWaste: tree.hazardousWaste ?? 2.0,
    materials: { ...(tree.materials || {}) },
    transport: { ...(tree.transport || {}) },
    telecom: { ...(tree.telecom || {}) },
    gas: { ...(tree.gas || {}) },
    refrigerant: { ...(tree.refrigerant || {}) },
    food: { ...(tree.food || {}) },
    maintenance: { ...(tree.maintenance || { service_unit: 0.1 }) },
    equipment: { ...(tree.equipment || { kg: 0.5 }) },
    recycling: tree.recycling ?? 0.08
  };
};

const getIndustryFactors = () => ({ ...(REGISTRY_DOC.industryFactors || {}) });

const getDomainFactors = () => {
  const domains = REGISTRY_DOC.domainFactors || {};
  const result = {};
  Object.entries(domains).forEach(([domain, factors]) => {
    result[domain] = { ...factors };
  });
  return result;
};

const getRegionalGridFactors = () => ({ ...(REGISTRY_DOC.regionalGridKgCo2PerKwh || {}) });

const getRegionalGridSource = () => ({ ...(REGISTRY_DOC.regionalGridSource || {}) });

const listRegistryFactorIds = () => Object.keys(DEFAULT_FACTOR_REGISTRY);

/** Maps activity-tree dot paths to MongoDB/registry factor IDs for runtime hydration. */
const ACTIVITY_FACTOR_REGISTRY_MAP = Object.freeze({
  'electricity.grid': 'electricity_grid_india',
  'electricity.renewable': 'electricity_renewable',
  'electricity.mixed': 'electricity_mixed',
  'electricity.gj': 'energy_gj',
  'fuel.diesel': 'fuel_diesel',
  'fuel.petrol': 'fuel_petrol',
  'fuel.lpg': 'fuel_lpg',
  'fuel.cng': 'fuel_cng',
  'fuel.coal': 'fuel_coal',
  'fuel.natural_gas': 'fuel_natural_gas',
  'fuel.biomass': 'fuel_biomass',
  water: 'water_consumption',
  sewage: 'sewage_disposal',
  wastewater: 'wastewater_treatment',
  solidWaste: 'waste_solid',
  hazardousWaste: 'waste_hazardous',
  'materials.steel': 'material_steel',
  'materials.aluminum': 'material_aluminum',
  'materials.plastic': 'material_plastic',
  'materials.paper': 'material_paper',
  'materials.glass': 'material_glass',
  'materials.wood': 'material_wood',
  'materials.concrete': 'material_concrete',
  'materials.cement': 'material_cement',
  'materials.copper': 'material_copper',
  'materials.cotton': 'material_cotton',
  'materials.polyester': 'material_polyester',
  'materials.zinc': 'material_zinc',
  'materials.rubber': 'material_rubber',
  'materials.ceramic': 'material_ceramic',
  'materials.electronics': 'material_electronics',
  'materials.fertilizer': 'material_fertilizer',
  'materials.battery': 'material_battery',
  'materials.sugar': 'material_sugar',
  'materials.paint': 'material_paint',
  'materials.industrial_paint': 'material_industrial_paint',
  'materials.solvent': 'material_solvent',
  'transport.diesel': 'fuel_diesel',
  'transport.petrol': 'fuel_petrol',
  'transport.cng': 'fuel_cng',
  'transport.rail': 'travel_rail_km',
  'transport.road': 'travel_road_km',
  'transport.car': 'travel_car_km',
  'transport.two_wheeler': 'travel_two_wheeler_km',
  'transport.auto': 'travel_auto_km',
  'transport.bus_pkm': 'travel_bus_pkm',
  'transport.commute': 'commute_km',
  'transport.tonkm': 'transport_road_tonkm',
  'transport.rail_tonkm': 'transport_rail_tonkm',
  'transport.sea_tonne': 'transport_sea_tonne',
  'transport.courier_kg': 'transport_courier_kg',
  'telecom.gb': 'telecom_data_gb',
  'gas.scm': 'fuel_natural_gas',
  'refrigerant.r22': 'refrigerant_r22',
  'refrigerant.r134a': 'refrigerant_r134a',
  'food.meal': 'food_meal_unit',
  'food.service_unit': 'food_meal_unit',
  'maintenance.service_unit': 'maintenance_service_unit',
  'equipment.kg': 'capital_goods_equipment_kg',
  recycling: 'cpcb_waste_recycling'
});

const setNestedFactor = (target, path, value) => {
  const parts = String(path).split('.');
  let cursor = target;
  parts.forEach((part, index) => {
    if (index === parts.length - 1) {
      cursor[part] = value;
      return;
    }
    if (!cursor[part] || typeof cursor[part] !== 'object') {
      cursor[part] = {};
    }
    cursor = cursor[part];
  });
};

/**
 * Overlay MongoDB-backed registry factors onto the JSON activity tree.
 * Falls back silently to JSON values when getActiveFactor returns null.
 */
const hydrateActivityEmissionFactors = async (getActiveFactor) => {
  const factors = getActivityEmissionFactors();
  const registryMeta = {};
  const lookups = Object.entries(ACTIVITY_FACTOR_REGISTRY_MAP).map(async ([path, factorId]) => {
    const row = await getActiveFactor(factorId);
    if (row?.factor == null || !Number.isFinite(Number(row.factor))) {
      return;
    }
    setNestedFactor(factors, path, Number(row.factor));
    registryMeta[path] = {
      factorId,
      registryBacked: row.registryBacked !== false,
      sourceVersion: row.sourceVersion || null
    };
  });
  await Promise.all(lookups);
  return { factors, registryMeta };
};

const regionalGridFactorId = (stateKey) => `regional_grid_${String(stateKey).toLowerCase().replace(/\s+/g, '_')}`;

/**
 * Overlay MongoDB-backed regional grid intensities (kgCO2e/kWh).
 */
const hydrateRegionalGridFactors = async (getActiveFactor) => {
  const regional = getRegionalGridFactors();
  const registryMeta = {};
  const lookups = Object.entries(regional).map(async ([stateKey, jsonValue]) => {
    const factorId = regionalGridFactorId(stateKey);
    const row = await getActiveFactor(factorId);
    if (row?.factor != null && Number.isFinite(Number(row.factor))) {
      regional[stateKey] = Number(row.factor);
      registryMeta[stateKey] = { factorId, registryBacked: row.registryBacked !== false };
      return;
    }
    registryMeta[stateKey] = { factorId, registryBacked: false, fallback: jsonValue };
  });
  await Promise.all(lookups);
  return { regional, registryMeta };
};

/**
 * Build CPCB factor lookup cache from MongoDB registry (falls back to JSON in resolver).
 */
const hydrateCpcbFactorCache = async (getActiveFactor) => {
  const cache = {};
  const registryMeta = {};
  await Promise.all(listCpcbFactorIds().map(async (factorId) => {
    const row = await getActiveFactor(factorId);
    if (row?.factor != null && Number.isFinite(Number(row.factor))) {
      cache[factorId] = {
        id: factorId,
        factor: Number(row.factor),
        unit: row.unit,
        source: row.source,
        registryBacked: row.registryBacked !== false,
        sourceVersion: row.sourceVersion || null
      };
      registryMeta[factorId] = { registryBacked: true };
    }
  }));
  return { cache, registryMeta };
};

const { getCpcbRegistryMetadata, listCpcbFactorIds, getCpcbFactor } = require('./cpcbEmissionFactors');

const getFactorsPackVersion = () => REGISTRY_DOC.factorsPackVersion || '0.0.0';

const getFuelUnitPolicy = (fuelType = '') => {
  const key = String(fuelType || '').toLowerCase();
  const policy = (REGISTRY_DOC.fuelUnitPolicy || {})[key];
  if (!policy) {
    return null;
  }
  const registryRow = DEFAULT_FACTOR_REGISTRY[`fuel_${key}`] || {};
  return {
    fuelType: key,
    factorUnit: policy.factorUnit || registryRow.unit || 'kgCO2e/liter',
    priceUnit: policy.priceUnit || 'INR/liter',
    densityKgPerLiter: Number.isFinite(Number(policy.densityKgPerLiter))
      ? Number(policy.densityKgPerLiter)
      : (Number.isFinite(Number(registryRow.densityKgPerLiter)) ? Number(registryRow.densityKgPerLiter) : null),
    literPolicy: policy.literPolicy || registryRow.literPolicy || null,
    notes: policy.notes || null
  };
};

const isMassPricedFuel = (fuelType = '') => {
  const policy = getFuelUnitPolicy(fuelType);
  return Boolean(policy && String(policy.priceUnit || '').includes('/kg'));
};

module.exports = {
  REGISTRY_VERSION: REGISTRY_DOC.registryVersion,
  FACTORS_PACK_VERSION: getFactorsPackVersion(),
  METHODOLOGY_NOTE: REGISTRY_DOC.methodologyNote,
  DEFAULT_FACTOR_REGISTRY,
  ACTIVITY_FACTOR_REGISTRY_MAP,
  regionalGridFactorId,
  getActivityEmissionFactors,
  hydrateActivityEmissionFactors,
  hydrateRegionalGridFactors,
  hydrateCpcbFactorCache,
  getIndustryFactors,
  getDomainFactors,
  getRegionalGridFactors,
  getRegionalGridSource,
  getFactorsPackVersion,
  getFuelUnitPolicy,
  isMassPricedFuel,
  listRegistryFactorIds,
  getCpcbRegistryMetadata,
  listCpcbFactorIds,
  getCpcbFactor
};
